"use client";
import { partnerLinks } from "@/lib/partnerLinks";
import React from "react";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faBook,
  faNewspaper,
  faThumbsUp,
} from "@fortawesome/free-solid-svg-icons";
import Destinations from "@/components/after-your-booking/destinations";

const benefits = [
  {
    icon: faNewspaper,
    title: "Increased Reservations",
    body: (
      <>
        <a
          href={partnerLinks.operatorApply}
          target="_blank"
          rel="noopener noreferrer"
          className="tw-font-semibold tw-text-[#854ec9]"
        >
          Operators
        </a>{" "}
        and{" "}
        <a
          href={partnerLinks.operatorApply}
          target="_blank"
          rel="noopener noreferrer"
          className="tw-font-semibold tw-text-[#854ec9]"
        >
          Travel Agents
        </a>
        , offer your customers around the world more payment options to enhance
        their booking experience.
      </>
    ),
  },
  {
    icon: faThumbsUp,
    title: "Increased Efficiency",
    body: "Streamline your internal payment and invoicing processes with our robust and secure global infrastructure, designed to optimize efficiency and ensure seamless transactions.",
  },
  {
    icon: faBook,
    title: "Greater Control",
    body: "Enhance your cash flow by having the flexibility to control when payments are remitted from your TravelShop Booking Wallet.",
  },
];

const steps = [
  {
    title: "Secure Payment Processing",
    body: "Customer payments are processed securely.",
  },
  {
    title: "Independent Payment Holding",
    body: "Customer payments are held separately for added security.",
  },
  {
    title: "Payment Splitting & Release",
    body: "Payments are automatically split and released as needed.",
  },
  {
    title: "Complete Control",
    body: "You decide when and how to remit your payments.",
  },
];

const PaymentSolutions = () => {
  return (
    <main className="tw-font-display tw-bg-white">
      {/* Hero */}
      <section className="tw-relative tw-overflow-hidden">
        <div
          className="tw-absolute tw-inset-0 tw-bg-cover tw-bg-center"
          style={{
            backgroundImage:
              "url('https://travelshopbooking.com/images/paymentSolutions.webp')",
          }}
          aria-hidden="true"
        />
        <div
          className="tw-absolute tw-inset-0"
          style={{
            background:
              "linear-gradient(180deg, rgba(20,16,28,0.45) 0%, rgba(20,16,28,0.55) 55%, rgba(20,16,28,0.82) 100%)",
          }}
          aria-hidden="true"
        />
        <div className="tw-relative tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10 tw-py-24 md:tw-py-32">
          <div className="tw-max-w-[760px]">
            <span className="tw-inline-flex tw-items-center tw-gap-2 tw-rounded-full tw-bg-white/10 tw-border tw-border-solid tw-border-white/20 tw-px-4 tw-py-1.5 tw-text-[13px] tw-font-semibold tw-text-white tw-backdrop-blur">
              Payment Solutions
            </span>
            <h1 className="tw-mt-5 tw-text-[clamp(30px,4.5vw,52px)] tw-font-bold tw-tracking-tight tw-leading-[1.05] tw-text-white tw-m-0">
              Seamless Payments for Planned Excursions
            </h1>
            <p className="tw-mt-5 tw-mb-0 tw-text-[17px] tw-leading-[1.6] tw-text-white/85 tw-max-w-[60ch]">
              End-to-end payment solutions with seamless processing and flexible
              remittance options to enhance your customers&apos; booking
              experience, streamline operations, and optimize your cash flow.
            </p>
          </div>
        </div>
      </section>

      {/* Intro */}
      <section className="tw-py-12 md:tw-py-16">
        <div className="tw-container tw-mx-auto tw-max-w-[820px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <p className="tw-m-0 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
            TravelShop Booking Payments simplifies online payment management and
            streamlines customer bookings for Organized Adventures. Our
            solutions support commission-free direct bookings and
            commission-based bookings through distribution channels like agents
            and creators. With features like automated invoicing, payment
            splitting, and release, we help grow your bookings, boost
            operational efficiency, and provide enhanced control — delivering a
            win-win for all parties!
          </p>
        </div>
      </section>

      {/* Benefits */}
      <section className="tw-pb-12 md:tw-pb-16">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-grid tw-grid-cols-1 md:tw-grid-cols-3 tw-gap-5 lg:tw-gap-6">
            {benefits.map((b) => (
              <div
                key={b.title}
                className="tw-rounded-2xl tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] tw-p-6 hover:tw-border-[#d8d2e1] hover:tw-shadow-lg tw-transition-all tw-duration-200"
              >
                <div className="tw-flex tw-h-12 tw-w-12 tw-items-center tw-justify-center tw-rounded-xl tw-bg-[#854ec9]/10 tw-text-[#854ec9]">
                  <FontAwesomeIcon icon={b.icon} className="tw-text-xl" />
                </div>
                <h3 className="tw-mt-4 tw-text-[17px] tw-font-bold tw-text-[#14101c] tw-m-0">
                  {b.title}
                </h3>
                <p className="tw-mt-2 tw-mb-0 tw-text-[14px] tw-leading-[1.6] tw-text-[#5d556c]">
                  {b.body}
                </p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* How it operates */}
      <section className="tw-py-12 md:tw-py-16 tw-bg-[#faf9fc]">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-2 tw-gap-10 lg:tw-gap-14 tw-items-center">
            <div>
              <h2 className="tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
                How It Operates
              </h2>
              <p className="tw-mt-4 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                Bookings and payments managed through TravelShop Booking
                Payments follow four simple steps:
              </p>
              <ol className="tw-mt-5 tw-m-0 tw-p-0 tw-list-none tw-space-y-4">
                {steps.map((step, i) => (
                  <li key={step.title} className="tw-flex tw-gap-4">
                    <span className="tw-flex tw-h-9 tw-w-9 tw-shrink-0 tw-items-center tw-justify-center tw-rounded-full tw-bg-[#854ec9] tw-text-white tw-text-[15px] tw-font-bold">
                      {i + 1}
                    </span>
                    <div>
                      <p className="tw-m-0 tw-text-[15px] tw-font-bold tw-text-[#14101c]">
                        {step.title}
                      </p>
                      <p className="tw-mt-1 tw-mb-0 tw-text-[14px] tw-leading-[1.6] tw-text-[#5d556c]">
                        {step.body}
                      </p>
                    </div>
                  </li>
                ))}
              </ol>
            </div>
            <div>
              <img
                src="/images/pay.jpg"
                alt="Payments"
                loading="lazy"
                className="tw-w-full tw-rounded-2xl tw-object-cover tw-shadow-xl tw-shadow-[#14101c]/10"
              />
            </div>
          </div>
        </div>
      </section>

      {/* Payment methods */}
      <section className="tw-py-12 md:tw-py-16">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-2 tw-gap-10 lg:tw-gap-14 tw-items-center">
            <div className="tw-order-2 lg:tw-order-1">
              <img
                src="/images/visacard.jpg"
                alt="Payment cards"
                loading="lazy"
                className="tw-w-full tw-rounded-2xl tw-object-cover tw-shadow-xl tw-shadow-[#14101c]/10"
              />
            </div>
            <div className="tw-order-1 lg:tw-order-2">
              <h2 className="tw-text-[clamp(22px,2.8vw,30px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
                A Variety of Payment Methods for Customers
              </h2>
              <p className="tw-mt-4 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                Your customers benefit from a smooth, secure, and fee-free
                payment experience by choosing their preferred payment method
                and plan.
              </p>
              <h3 className="tw-mt-5 tw-text-[16px] tw-font-bold tw-text-[#14101c]">
                Accepted Payment Options
              </h3>
              <p className="tw-mt-2 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                Customers can select from Visa, Mastercard, and Maestro.
                Depending on their location, they can also pay in AUD, CAD, EUR,
                GBP, NZD, or USD for added convenience.
              </p>
              <h3 className="tw-mt-5 tw-text-[16px] tw-font-bold tw-text-[#14101c]">
                Available Payment Plans
              </h3>
              <p className="tw-mt-2 tw-mb-0 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                We offer various payment plans based on how far in advance the
                departure date is — paying a small deposit with the balance
                later, splitting into installments, or paying the full amount
                upfront. Processing is fully automated through our local
                companies in Australia, Canada, Europe, and the US.
              </p>
            </div>
          </div>
        </div>
      </section>

      {/* Simplified pricing */}
      <section className="tw-py-12 md:tw-py-16 tw-bg-[#faf9fc]">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-2 tw-gap-10 lg:tw-gap-14 tw-items-center">
            <div>
              <h2 className="tw-text-[clamp(22px,2.8vw,30px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
                Simplified Pricing for Operators
              </h2>
              <p className="tw-mt-4 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                Payment processing can be a headache when dealing with customers
                across various countries, currencies, and channels. TravelShop
                Booking offers a single set fee per currency based on the
                customer&apos;s location — regardless of their preferred payment
                method, whether the:
              </p>
              <ul className="tw-mt-4 tw-m-0 tw-pl-5 tw-space-y-1.5 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                <li>payment method is Visa, Mastercard, or Maestro</li>
                <li>payment plan is pay now or pay later</li>
                <li>
                  channel is the{" "}
                  <a
                    href="/"
                    target="_blank"
                    rel="noopener noreferrer"
                    className="tw-font-semibold tw-text-[#854ec9]"
                  >
                    TravelShop Booking Marketplace
                  </a>
                  ,{" "}
                  <a
                    href={partnerLinks.operatorApply}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="tw-font-semibold tw-text-[#854ec9]"
                  >
                    agents
                  </a>
                  , or{" "}
                  <a
                    href={partnerLinks.operatorApply}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="tw-font-semibold tw-text-[#854ec9]"
                  >
                    White Label
                  </a>
                </li>
              </ul>
              <p className="tw-mt-4 tw-mb-0 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                Our goal is to make payment processing costs clear and easy for
                operators to understand — transparency and simplicity in every
                transaction.
              </p>
            </div>
            <div>
              <img
                src="/images/currency.webp"
                alt="Currencies"
                loading="lazy"
                className="tw-w-full tw-rounded-2xl tw-object-cover tw-shadow-xl tw-shadow-[#14101c]/10"
              />
            </div>
          </div>
        </div>
      </section>

      {/* Trust */}
      <section className="tw-py-12 md:tw-py-16">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-2 tw-gap-10 lg:tw-gap-14 tw-items-center">
            <div className="tw-order-2 lg:tw-order-1">
              <img
                src="/images/womanpay.avif"
                alt="Secure payment"
                loading="lazy"
                className="tw-w-full tw-rounded-2xl tw-object-cover tw-shadow-xl tw-shadow-[#14101c]/10"
              />
            </div>
            <div className="tw-order-1 lg:tw-order-2">
              <h2 className="tw-text-[clamp(22px,2.8vw,30px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
                Building trust and transparency for everyone involved
              </h2>
              <p className="tw-mt-4 tw-mb-0 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                TravelShop Booking Payments adheres to global payment
                regulations, helping you reduce fraud and disputes. Our
                all-in-one accounts payable and receivable solution saves time
                and money by automatically invoicing, processing, and securely
                holding customer bookings and payments. Funds are held
                independently with a globally recognized company until they are
                automatically split and safely released to the operator, agent,
                and creator&apos;s Wallets.
              </p>
            </div>
          </div>
        </div>
      </section>

      {/* Full control */}
      <section className="tw-py-12 md:tw-py-16 tw-bg-[#faf9fc]">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-2 tw-gap-10 lg:tw-gap-14 tw-items-center">
            <div>
              <h2 className="tw-text-[clamp(22px,2.8vw,30px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
                Full Control in Your Hands
              </h2>
              <p className="tw-mt-4 tw-mb-0 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                We&apos;re here to help you enhance your cash flow while
                ensuring the security of customer payments. With no minimum
                payment release thresholds, businesses in the Organized
                Adventure industry can easily control when to remit payments
                from your Wallet to your preferred account in over 200 supported
                countries and regions, and in 50+ currencies.
              </p>
            </div>
            <div>
              <img
                src="/images/manpay.avif"
                alt="Payment control"
                loading="lazy"
                className="tw-w-full tw-rounded-2xl tw-object-cover tw-shadow-xl tw-shadow-[#14101c]/10"
              />
            </div>
          </div>
        </div>
      </section>

      <Destinations />
    </main>
  );
};

export default PaymentSolutions;
